# domain/order.rb - plain Ruby, invariants in the constructor
class Order
  def initialize(id:, lines:)
    raise ArgumentError, "order needs lines" if lines.empty?
    @id, @lines = id, lines.freeze
  end
end
# infrastructure/order_repository.rb
class OrderRepository
  def find(id) = OrderMapper.to_domain(OrderRecord.find(id))
  def save(order) = OrderRecord.upsert(OrderMapper.to_record(order))
end
